#  DDD: Domain Services + Repository + Full Example
#  Complete working DDD implementation
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import List, Optional, Dict
from datetime import datetime
from enum import Enum
import uuid

# ══════════════════════════════════════════════════
#  VALUE OBJECTS
# ══════════════════════════════════════════════════

@dataclass(frozen=True)
class Money:
    amount  : float
    currency: str = "INR"

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError(f"Money cannot be negative: {self.amount}")
        object.__setattr__(self, 'amount', round(self.amount, 2))

    def __add__(self, other: 'Money') -> 'Money':
        self._same_currency(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: 'Money') -> 'Money':
        self._same_currency(other)
        return Money(max(0, self.amount - other.amount), self.currency)

    def __mul__(self, factor: float) -> 'Money':
        return Money(round(self.amount * factor, 2), self.currency)

    def __gt__(self, other: 'Money') -> bool:
        self._same_currency(other); return self.amount > other.amount

    def __ge__(self, other: 'Money') -> bool:
        self._same_currency(other); return self.amount >= other.amount

    def _same_currency(self, other):
        if self.currency != other.currency:
            raise ValueError(f"Currency mismatch: {self.currency} ≠ {other.currency}")

    def __str__(self):
        return f"₹{self.amount:,.2f}"

@dataclass(frozen=True)
class ProductId:
    value: str
    def __str__(self): return self.value

@dataclass(frozen=True)
class CustomerId:
    value: str
    def __str__(self): return self.value

@dataclass(frozen=True)
class OrderId:
    value: str = field(default_factory=lambda: f"ORD-{str(uuid.uuid4())[:8].upper()}")
    def __str__(self): return self.value

@dataclass(frozen=True)
class Quantity:
    value: int

    def __post_init__(self):
        if self.value <= 0:
            raise ValueError(f"Quantity must be positive, got {self.value}")

    def __add__(self, other: 'Quantity') -> 'Quantity':
        return Quantity(self.value + other.value)

    def __sub__(self, other: 'Quantity') -> 'Quantity':
        if self.value < other.value:
            raise ValueError("Cannot subtract to negative quantity")
        return Quantity(self.value - other.value)

    def __ge__(self, other: 'Quantity') -> bool:
        return self.value >= other.value

    def __str__(self): return str(self.value)

# ══════════════════════════════════════════════════
#  DOMAIN EVENTS
# ══════════════════════════════════════════════════

@dataclass(frozen=True)
class DomainEvent(ABC):
    event_id    : str = field(default_factory=lambda: str(uuid.uuid4()))
    occurred_at : str = field(default_factory=lambda: datetime.now().isoformat())

    @property
    def name(self): return self.__class__.__name__

@dataclass(frozen=True)
class OrderPlaced(DomainEvent):
    order_id   : str = ""
    customer_id: str = ""
    total      : float = 0.0

@dataclass(frozen=True)
class OrderConfirmed(DomainEvent):
    order_id   : str = ""
    customer_id: str = ""

@dataclass(frozen=True)
class OrderCancelled(DomainEvent):
    order_id: str = ""
    reason  : str = ""

@dataclass(frozen=True)
class PaymentReceived(DomainEvent):
    order_id      : str = ""
    amount        : float = 0.0
    transaction_id: str = ""

@dataclass(frozen=True)
class ProductRestocked(DomainEvent):
    product_id: str = ""
    qty_added : int = 0
    new_stock  : int = 0

@dataclass(frozen=True)
class StockDepleted(DomainEvent):
    product_id  : str = ""
    product_name: str = ""

# ══════════════════════════════════════════════════
#  ENTITIES + AGGREGATE ROOTS
# ══════════════════════════════════════════════════

class AggregateRoot:
    """Base for all Aggregate Roots — manages domain events"""

    def __init__(self):
        self._events: List[DomainEvent] = []

    def _record(self, event: DomainEvent):
        self._events.append(event)
        print(f"  📌 Event recorded: {event.name}")

    @property
    def domain_events(self) -> List[DomainEvent]:
        return list(self._events)

    def clear_events(self):
        self._events.clear()

# ──────────────────────────────────────────────────
#  PRODUCT AGGREGATE
# ──────────────────────────────────────────────────
class Product(AggregateRoot):
    """
    Product Aggregate Root.
    Owns: stock management, pricing, availability rules.
    Invariant: stock cannot go negative.
    """

    def __init__(self, product_id: ProductId, name: str,
                 price: Money, initial_stock: Quantity,
                 category: str = "General",
                 low_stock_threshold: int = 5):
        super().__init__()
        self._id         = product_id
        self.name        = name
        self._price      = price
        self._stock      = initial_stock
        self.category    = category
        self._threshold  = low_stock_threshold
        self._available  = True

    @property
    def id(self) -> ProductId:      return self._id
    @property
    def price(self) -> Money:       return self._price
    @property
    def stock(self) -> Quantity:    return self._stock
    @property
    def is_available(self) -> bool: return self._available

    @property
    def is_low_stock(self) -> bool:
        return self._stock.value <= self._threshold

    def can_fulfill(self, qty: Quantity) -> bool:
        return self._available and self._stock >= qty

    def reserve_stock(self, qty: Quantity):
        """
        Business rule: Cannot reserve more than available.
        This is the CORE INVARIANT of the Product aggregate.
        """
        if not self._available:
            raise ValueError(f"Product '{self.name}' is not available")
        if not (self._stock >= qty):
            raise ValueError(
                f"Insufficient stock for '{self.name}': "
                f"have {self._stock}, need {qty}"
            )
        self._stock = self._stock - qty
        print(f"  📦 Reserved {qty} of '{self.name}' "
              f"(remaining: {self._stock})")

        if self._stock.value == 0:
            self._available = False
            self._record(StockDepleted(
                product_id   = str(self._id),
                product_name = self.name
            ))
        elif self.is_low_stock:
            print(f"  ⚠️  Low stock alert: '{self.name}' "
                  f"({self._stock} remaining)")

    def restock(self, qty: Quantity):
        self._stock    = self._stock + qty
        self._available = True
        print(f"  📦 Restocked '{self.name}': +{qty} (total: {self._stock})")
        self._record(ProductRestocked(
            product_id = str(self._id),
            qty_added  = qty.value,
            new_stock  = self._stock.value
        ))

    def update_price(self, new_price: Money):
        old = self._price
        self._price = new_price
        print(f"  💰 '{self.name}' price: {old} → {new_price}")

    def __repr__(self):
        return (f"Product({self.name}, {self._price}, "
                f"stock={self._stock}, "
                f"{'✅' if self._available else '❌'})")

# ──────────────────────────────────────────────────
#  ORDER AGGREGATE
# ──────────────────────────────────────────────────
@dataclass(frozen=True)
class OrderLine:
    """Value Object inside Order aggregate"""
    product_id  : ProductId
    product_name: str
    quantity    : Quantity
    unit_price  : Money

    @property
    def subtotal(self) -> Money:
        return self.unit_price * self.quantity.value

    def __str__(self):
        return (f"{self.product_name} × {self.quantity} "
                f"@ {self.unit_price} = {self.subtotal}")

class OrderStatus(Enum):
    DRAFT     = "draft"
    CONFIRMED = "confirmed"
    PAID      = "paid"
    PROCESSING= "processing"
    SHIPPED   = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"

class Order(AggregateRoot):
    """
    Order Aggregate Root.
    Invariants:
    - Cannot add items to non-draft orders
    - Total must exceed minimum before confirmation
    - Payment must match total exactly
    - Cannot cancel paid/shipped/delivered orders
    """
    MIN_ORDER_AMOUNT = Money(100)
    MAX_LINES        = 25

    def __init__(self, order_id: OrderId, customer_id: CustomerId):
        super().__init__()
        self._id          = order_id
        self._customer_id = customer_id
        self._lines       : List[OrderLine] = []
        self._status      = OrderStatus.DRAFT
        self._created_at  = datetime.now()
        self._paid_at     = None
        self._transaction_id = None

        self._record(OrderPlaced(
            order_id    = str(order_id),
            customer_id = str(customer_id),
            total       = 0.0
        ))

    @property
    def id(self) -> OrderId:
        return self._id

    @property
    def customer_id(self) -> CustomerId:
        return self._customer_id

    @property
    def status(self) -> OrderStatus:
        return self._status

    @property
    def lines(self) -> List[OrderLine]:
        return list(self._lines)

    @property
    def total(self) -> Money:
        if not self._lines:
            return Money(0)
        totals = [line.subtotal for line in self._lines]
        return sum(totals, Money(0))

    @property
    def line_count(self) -> int:
        return len(self._lines)

    # ─── Commands (actions that change state) ───
    def add_line(self, product_id: ProductId, product_name: str,
                 quantity: Quantity, unit_price: Money):
        self._assert_status(OrderStatus.DRAFT, "add items to")

        if self.line_count >= self.MAX_LINES:
            raise ValueError(
                f"Order cannot exceed {self.MAX_LINES} lines"
            )

        # Update existing line if product already in order
        for i, line in enumerate(self._lines):
            if line.product_id == product_id:
                new_qty  = line.quantity + quantity
                new_line = OrderLine(product_id, product_name,
                                     new_qty, unit_price)
                self._lines[i] = new_line
                print(f"  🛒 Updated: {new_line}")
                return

        line = OrderLine(product_id, product_name, quantity, unit_price)
        self._lines.append(line)
        print(f"  🛒 Added: {line}")

    def remove_line(self, product_id: ProductId):
        self._assert_status(OrderStatus.DRAFT, "remove items from")
        before = len(self._lines)
        self._lines = [l for l in self._lines
                       if l.product_id != product_id]
        if len(self._lines) == before:
            raise ValueError(f"Product {product_id} not in order")

    def confirm(self):
        self._assert_status(OrderStatus.DRAFT, "confirm")
        if not self._lines:
            raise ValueError("Cannot confirm an empty order")
        if not (self.total >= self.MIN_ORDER_AMOUNT):
            raise ValueError(
                f"Order total {self.total} is below "
                f"minimum {self.MIN_ORDER_AMOUNT}"
            )

        self._status = OrderStatus.CONFIRMED
        print(f"  ✅ Order {self._id} confirmed — total: {self.total}")
        self._record(OrderConfirmed(
            order_id    = str(self._id),
            customer_id = str(self._customer_id)
        ))

    def record_payment(self, amount: Money, transaction_id: str):
        self._assert_status(OrderStatus.CONFIRMED, "pay for")
        if amount != self.total:
            raise ValueError(
                f"Payment {amount} doesn't match order total {self.total}"
            )
        self._status         = OrderStatus.PAID
        self._paid_at        = datetime.now()
        self._transaction_id = transaction_id
        print(f"  💳 Payment recorded: {amount} | TXN: {transaction_id}")
        self._record(PaymentReceived(
            order_id       = str(self._id),
            amount         = amount.amount,
            transaction_id = transaction_id
        ))

    def cancel(self, reason: str):
        if self._status in (OrderStatus.PAID, OrderStatus.SHIPPED,
                            OrderStatus.DELIVERED):
            raise ValueError(
                f"Cannot cancel order in '{self._status.value}' status"
            )
        self._status = OrderStatus.CANCELLED
        print(f"  🚫 Order {self._id} cancelled: {reason}")
        self._record(OrderCancelled(
            order_id = str(self._id),
            reason   = reason
        ))

    def _assert_status(self, expected: OrderStatus, action: str):
        if self._status != expected:
            raise ValueError(
                f"Cannot {action} an order in "
                f"'{self._status.value}' status"
            )

    def print_receipt(self):
        print(f"\n  {'═'*50}")
        print(f"  ORDER RECEIPT")
        print(f"  {'─'*50}")
        print(f"  Order ID   : {self._id}")
        print(f"  Customer   : {self._customer_id}")
        print(f"  Status     : {self._status.value.upper()}")
        print(f"  {'─'*50}")
        for line in self._lines:
            print(f"  {line}")
        print(f"  {'─'*50}")
        print(f"  TOTAL      : {self.total}")
        if self._transaction_id:
            print(f"  TXN        : {self._transaction_id}")
        print(f"  {'═'*50}")

    def __repr__(self):
        return (f"Order({self._id}, {self._status.value}, "
                f"{self.line_count} lines, {self.total})")

# ══════════════════════════════════════════════════
#  REPOSITORIES (Interfaces)
# ══════════════════════════════════════════════════

class ProductRepository(ABC):
    @abstractmethod
    def save(self, product: Product) -> None: pass

    @abstractmethod
    def find_by_id(self, product_id: ProductId) -> Optional[Product]: pass

    @abstractmethod
    def find_by_category(self, category: str) -> List[Product]: pass

    @abstractmethod
    def find_available(self) -> List[Product]: pass

    @abstractmethod
    def find_low_stock(self, threshold: int = 5) -> List[Product]: pass

class OrderRepository(ABC):
    @abstractmethod
    def save(self, order: Order) -> None: pass

    @abstractmethod
    def find_by_id(self, order_id: OrderId) -> Optional[Order]: pass

    @abstractmethod
    def find_by_customer(self, customer_id: CustomerId) -> List[Order]: pass

    @abstractmethod
    def find_by_status(self, status: OrderStatus) -> List[Order]: pass

# ──────────────────────────────────────────────────
#  IN-MEMORY IMPLEMENTATIONS
# ──────────────────────────────────────────────────

class InMemoryProductRepository(ProductRepository):
    def __init__(self):
        self._store: Dict[str, Product] = {}

    def save(self, product: Product):
        self._store[str(product.id)] = product

    def find_by_id(self, product_id: ProductId) -> Optional[Product]:
        return self._store.get(str(product_id))

    def find_by_category(self, category: str) -> List[Product]:
        return [p for p in self._store.values()
                if p.category == category]

    def find_available(self) -> List[Product]:
        return [p for p in self._store.values() if p.is_available]

    def find_low_stock(self, threshold=5) -> List[Product]:
        return [p for p in self._store.values()
                if p.stock.value <= threshold]

class InMemoryOrderRepository(OrderRepository):
    def __init__(self):
        self._store: Dict[str, Order] = {}

    def save(self, order: Order):
        self._store[str(order.id)] = order

    def find_by_id(self, order_id: OrderId) -> Optional[Order]:
        return self._store.get(str(order_id))

    def find_by_customer(self, customer_id: CustomerId) -> List[Order]:
        return [o for o in self._store.values()
                if str(o.customer_id) == str(customer_id)]

    def find_by_status(self, status: OrderStatus) -> List[Order]:
        return [o for o in self._store.values()
                if o.status == status]

# ══════════════════════════════════════════════════
#  DOMAIN SERVICE
#  Business logic that doesn't fit in ONE entity.
#  OrderFulfillmentService coordinates Order + Product.
# ══════════════════════════════════════════════════

class OrderFulfillmentService:
    """
    Domain Service: coordinates the Order and Product aggregates.
    Contains business logic that spans MULTIPLE aggregates.
    Rule: if it naturally belongs to one aggregate → put it there.
          if it involves multiple aggregates → Domain Service.
    """

    def __init__(self,
                 order_repo  : OrderRepository,
                 product_repo: ProductRepository,
                 event_bus   : 'EventBus'):
        self._orders   = order_repo
        self._products = product_repo
        self._events   = event_bus

    def place_order(self,
                    customer_id : CustomerId,
                    cart_items  : List[dict]) -> Order:
        """
        Orchestrates: create order → verify products →
                      reserve stock → confirm order → dispatch events.
        This is a UNIT OF WORK — all steps succeed or all rollback.
        """
        print(f"\n{'═'*55}")
        print(f"  PLACING ORDER for customer {customer_id}")
        print(f"{'═'*55}")

        order = Order(OrderId(), customer_id)
        reserved_products = []

        try:
            # Step 1: Verify all products and build order lines
            for item in cart_items:
                pid     = ProductId(item['product_id'])
                qty     = Quantity(item['quantity'])
                product = self._products.find_by_id(pid)

                if not product:
                    raise ValueError(
                        f"Product '{item['product_id']}' not found"
                    )
                if not product.can_fulfill(qty):
                    raise ValueError(
                        f"Cannot fulfill {qty} of '{product.name}' "
                        f"(available: {product.stock})"
                    )

                order.add_line(pid, product.name, qty, product.price)

            # Step 2: Confirm the order (validates business rules)
            order.confirm()

            # Step 3: Reserve stock across all products
            for item in cart_items:
                pid     = ProductId(item['product_id'])
                qty     = Quantity(item['quantity'])
                product = self._products.find_by_id(pid)
                product.reserve_stock(qty)
                self._products.save(product)
                reserved_products.append((product, qty))

            # Step 4: Persist order
            self._orders.save(order)

            # Step 5: Dispatch all domain events
            self._events.dispatch_aggregate(order)
            for product, _ in reserved_products:
                self._events.dispatch_aggregate(product)

            print(f"\n  🎉 Order placed successfully: {order.id}")
            return order

        except Exception as e:
            # Rollback stock reservations
            print(f"\n  ❌ Order failed: {e} — rolling back")
            for product, qty in reserved_products:
                product.restock(qty)   # give stock back
                self._products.save(product)
            raise

    def process_payment(self, order_id: OrderId,
                         amount: Money,
                         transaction_id: str) -> Order:
        """Handles payment for a confirmed order"""
        order = self._orders.find_by_id(order_id)
        if not order:
            raise ValueError(f"Order {order_id} not found")

        order.record_payment(amount, transaction_id)
        self._orders.save(order)
        self._events.dispatch_aggregate(order)
        return order

    def cancel_order(self, order_id: OrderId,
                      reason: str) -> Order:
        """Cancel order and release reserved stock"""
        order = self._orders.find_by_id(order_id)
        if not order:
            raise ValueError(f"Order {order_id} not found")

        # Release stock for each line
        for line in order.lines:
            product = self._products.find_by_id(line.product_id)
            if product:
                product.restock(line.quantity)
                self._products.save(product)

        order.cancel(reason)
        self._orders.save(order)
        self._events.dispatch_aggregate(order)
        return order

    def get_customer_order_history(self,
                                    customer_id: CustomerId) -> dict:
        """Query service — reads across aggregates"""
        orders = self._orders.find_by_customer(customer_id)
        paid_orders = [o for o in orders
                       if o.status == OrderStatus.PAID]
        total_spent = sum(
            (o.total.amount for o in paid_orders), 0.0
        )
        return {
            "customer_id" : str(customer_id),
            "total_orders": len(orders),
            "paid_orders" : len(paid_orders),
            "total_spent" : Money(total_spent),
            "orders"      : orders
        }

# ══════════════════════════════════════════════════
#  APPLICATION SERVICE + EVENT BUS
# ══════════════════════════════════════════════════

class EventBus:
    """Dispatches domain events to application-level handlers"""

    def __init__(self):
        self._handlers: Dict[type, list] = {}

    def subscribe(self, event_type: type, handler):
        self._handlers.setdefault(event_type, []).append(handler)

    def dispatch_aggregate(self, aggregate: AggregateRoot):
        dispatched = 0
        for event in aggregate.domain_events:
            for handler in self._handlers.get(type(event), []):
                handler(event)
                dispatched += 1
        aggregate.clear_events()
        return dispatched

# ══════════════════════════════════════════════════
#  APPLICATION LAYER — wires everything together
# ══════════════════════════════════════════════════

def setup_application():
    """Application composition root — wires all dependencies"""

    # Infrastructure
    product_repo = InMemoryProductRepository()
    order_repo   = InMemoryOrderRepository()
    event_bus    = EventBus()

    # Domain Service
    fulfillment = OrderFulfillmentService(
        order_repo, product_repo, event_bus
    )

    # Register event handlers (application-level reactions)
    def on_order_confirmed(event: OrderConfirmed):
        print(f"  📧 [APP] Confirmation email queued for {event.order_id}")

    def on_payment_received(event: PaymentReceived):
        print(f"  💰 [APP] Revenue recorded: ₹{event.amount:,.2f}")
        print(f"  📊 [APP] Analytics event sent")

    def on_order_cancelled(event: OrderCancelled):
        print(f"  📧 [APP] Cancellation notification sent")
        print(f"  💸 [APP] Refund initiated if paid")

    def on_stock_depleted(event: StockDepleted):
        print(f"  🚨 [APP] ALERT: '{event.product_name}' is OUT OF STOCK!")
        print(f"  📋 [APP] Purchase order raised automatically")

    def on_product_restocked(event: ProductRestocked):
        print(f"  ✅ [APP] Product restocked: +{event.qty_added} units")
        print(f"  📧 [APP] Back-in-stock notifications sent")

    event_bus.subscribe(OrderConfirmed,   on_order_confirmed)
    event_bus.subscribe(PaymentReceived,  on_payment_received)
    event_bus.subscribe(OrderCancelled,   on_order_cancelled)
    event_bus.subscribe(StockDepleted,    on_stock_depleted)
    event_bus.subscribe(ProductRestocked, on_product_restocked)

    return product_repo, order_repo, fulfillment, event_bus

# ══════════════════════════════════════════════════
#  FULL SCENARIO — Everything working together
# ══════════════════════════════════════════════════

print("=" * 55)
print("  DDD: Complete E-Commerce Domain")
print("=" * 55)

product_repo, order_repo, fulfillment, event_bus = setup_application()

# ─── Seed Products ───
print("\n--- Setting Up Product Catalog ---")
products_data = [
    ("P001", "MacBook Pro 14\"", Money(185000), Quantity(10), "Electronics"),
    ("P002", "Magic Mouse",      Money(6500),   Quantity(25), "Electronics"),
