    ("P004", "Laptop Bag",       Money(2500),   Quantity(15), "Accessories"),
    ("P005", "Monitor 27\"",     Money(35000),  Quantity(8),  "Electronics"),
]

for pid, name, price, qty, cat in products_data:
    p = Product(ProductId(pid), name, price, qty, cat)
    product_repo.save(p)
    print(f"  ✅ {p}")

# ─── Customer 1: Normal order flow ───
print("\n" + "─"*55)
print("SCENARIO 1: Alice places and pays for an order")
print("─"*55)

alice_id = CustomerId("CUST-ALICE")
order1 = fulfillment.place_order(alice_id, [
    {"product_id": "P001", "quantity": 1},
    {"product_id": "P002", "quantity": 2},
    {"product_id": "P004", "quantity": 1},
])
order1.print_receipt()

print("\n--- Alice pays ---")
