order1.print_receipt()

# ─── Customer 2: Low stock scenario ───
print("\n" + "─"*55)
print("SCENARIO 2: Bob orders the last USB-C Hubs (stock=3)")
print("─"*55)

bob_id = CustomerId("CUST-BOB")
order2 = fulfillment.place_order(bob_id, [
    {"product_id": "P003", "quantity": 3},  # takes ALL stock!
